52	    /// Sends exactly once; for callers that must not retry.
53	    pub async fn send_once(&self, req: Request) -> Result<Response, RpcError> {
54	        let http = self.build_request(&req)?;
55	        let timeout = self.config.timeout;
56	        let resp = self.transport.execute(http, timeout).await?;
57	        if resp.status().is_server_error() {
58	            tracing::debug!(status = %resp.status(), method = %req.method, "send_once: server error");
59	        }
60	        Ok(resp)
61	    }
